      crmAfter: after?.crm ?? null,
      outreachAfter: after?.outreach ?? null,
      ideasAfter: after?.ideas ?? null,
    });
  } catch (error) {
    return ownerOnlyJson(
      { ok: false, error: error instanceof Error ? error.message : 'Autonomous run failed.' },
      500,
    );
  }
